import { type ButtonHTMLAttributes, type FormEvent, type HTMLAttributes, type ReactNode, useEffect, useMemo, useState } from 'react';
import { QueryClient, QueryClientProvider, useQueryClient } from '@tanstack/react-query';
import { Link, Route, Switch, useLocation, Router as WouterRouter } from 'wouter';
import { AlertCircle, ArrowUpRight, BarChart3, BriefcaseBusiness, Building2, CalendarDays, Check, ChevronDown, CircleHelp, Clock3, Coins, Database, Fingerprint, Globe2, LayoutDashboard, LifeBuoy, Menu, Network, Plus, RefreshCw, Search, ShieldCheck, SlidersHorizontal, Users, X, Zap } from 'lucide-react';
import { Toaster, toast } from 'sonner';
import { ErrorBoundary } from '@/components/error-boundary';
import NotFound from '@/pages/not-found';
import {
  useGetWorkspace, useGetDashboardSummary, useListDepartments, useCreateDepartment,
  useListBranches, useCreateBranch, useListEmployees, useCreateEmployee, useGetEmployee,
  useUpdateEmployee, useGetAttendanceToday, useListAttendanceHistory, useCheckIn, useCheckOut,
  useListLeaveBalances, useListLeaveRequests, useCreateLeaveRequest, useDecideLeaveRequest,
  useListPermissionRequests, useCreatePermissionRequest, useDecidePermissionRequest,
  useGetAttendanceRules, useUpdateAttendanceRules, useGetAttendanceReport,
  useListPayrollPeriods, useCalculatePayroll, useListDevices, useCreateDevice, useSyncDevice,
  useGetSubscription, useListPlatformCompanies,
  getGetWorkspaceQueryKey, getGetDashboardSummaryQueryKey, getListDepartmentsQueryKey,
  getListBranchesQueryKey, getListEmployeesQueryKey, getGetEmployeeQueryKey,
  getGetAttendanceTodayQueryKey, getListAttendanceHistoryQueryKey, getListLeaveBalancesQueryKey,
  getListLeaveRequestsQueryKey, getListPermissionRequestsQueryKey, getGetAttendanceRulesQueryKey,
  getGetAttendanceReportQueryKey, getListPayrollPeriodsQueryKey, getListDevicesQueryKey,
  getGetSubscriptionQueryKey, getListPlatformCompaniesQueryKey,
} from '@workspace/api-client-react';

const queryClient = new QueryClient();
const fallbackWorkspace = { company: { id: 'demo', name: 'VAR HR workspace', slug: 'demo', timezone: 'UTC', currency: 'USD' }, role: 'company_owner', locale: 'en', direction: 'ltr', capabilities: [] } as any;

const nav = [
  { href: '/', label: 'Overview', icon: LayoutDashboard },
  { href: '/employees', label: 'Employees', icon: Users },
  { href: '/attendance', label: 'Attendance', icon: Clock3 },
  { href: '/requests', label: 'Requests', icon: CalendarDays },
  { href: '/rules', label: 'Rules', icon: SlidersHorizontal },
  { href: '/reports', label: 'Reports', icon: BarChart3 },
  { href: '/payroll', label: 'Payroll', icon: Coins },
  { href: '/devices', label: 'Devices', icon: Fingerprint },
];
const secondaryNav = [
  { href: '/subscription', label: 'Subscription', icon: Zap },
  { href: '/platform', label: 'Platform owner', icon: Network },
];

function cn(...parts: Array<string | false | null | undefined>) { return parts.filter(Boolean).join(' '); }
function money(value: number | undefined, currency = 'USD') { return new Intl.NumberFormat(undefined, { style: 'currency', currency, maximumFractionDigits: 0 }).format(value || 0); }
function date(value?: string) { if (!value) return '—'; return new Intl.DateTimeFormat(undefined, { day: '2-digit', month: 'short', year: 'numeric' }).format(new Date(value)); }
function time(value?: string | null) { if (!value) return '—'; return new Intl.DateTimeFormat(undefined, { hour: '2-digit', minute: '2-digit' }).format(new Date(value)); }

function Button({ children, variant = 'primary', className = '', ...props }: ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'quiet' | 'outline' | 'danger' }) {
  return <button {...props} className={cn('inline-flex items-center justify-center gap-2 rounded-lg px-3.5 py-2 text-sm font-semibold transition-all duration-200 focus-visible:ring-2 disabled:cursor-not-allowed disabled:opacity-50', variant === 'primary' && 'bg-primary text-primary-foreground hover:brightness-110', variant === 'quiet' && 'text-muted-foreground hover:bg-muted hover:text-foreground', variant === 'outline' && 'border border-border bg-card text-foreground hover:border-primary/50 hover:bg-muted/40', variant === 'danger' && 'border border-destructive/20 bg-destructive/10 text-destructive hover:bg-destructive/15', className)} />;
}
function Card({ children, className = '', ...props }: HTMLAttributes<HTMLDivElement>) { return <section {...props} className={cn('rounded-xl border border-border bg-card shadow-[var(--shadow-sm)]', className)}>{children}</section>; }
function Badge({ children, tone = 'neutral', ...props }: { children: ReactNode; tone?: 'neutral' | 'good' | 'warn' | 'bad' | 'accent' }) { return <span {...props} className={cn('inline-flex items-center rounded-full px-2 py-1 text-[11px] font-bold uppercase tracking-[.08em]', tone === 'good' && 'bg-primary/10 text-primary', tone === 'warn' && 'bg-accent/15 text-[#9b512e]', tone === 'bad' && 'bg-destructive/10 text-destructive', tone === 'accent' && 'bg-secondary/10 text-secondary', tone === 'neutral' && 'bg-muted text-muted-foreground')}>{children}</span>; }
function Skeleton({ className = '' }: { className?: string }) { return <div className={cn('animate-pulse rounded-md bg-muted', className)} />; }
function Empty({ title, detail, action }: { title: string; detail: string; action?: ReactNode }) { return <div className="flex min-h-44 flex-col items-center justify-center p-8 text-center"><div className="mb-3 rounded-full bg-muted p-3 text-muted-foreground"><Database size={18} /></div><h3 className="font-display font-semibold">{title}</h3><p className="mt-1 max-w-sm text-sm text-muted-foreground">{detail}</p>{action && <div className="mt-4">{action}</div>}</div>; }
function ErrorState({ retry }: { retry: () => void }) { return <div className="flex min-h-36 flex-col items-center justify-center gap-2 p-6 text-center"><AlertCircle className="text-destructive" size={22} /><p className="text-sm font-semibold">The operational feed could not be loaded.</p><p className="text-xs text-muted-foreground">Check the workspace connection and try again.</p><Button variant="outline" onClick={retry}>Retry</Button></div>; }
function SectionTitle({ eyebrow, title, detail, action }: { eyebrow?: string; title: string; detail?: string; action?: ReactNode }) { return <div className="mb-6 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="mb-1 text-[11px] font-bold uppercase tracking-[.16em] text-primary">{eyebrow}</p><h1 className="font-display text-2xl font-semibold tracking-tight sm:text-3xl">{title}</h1>{detail && <p className="mt-1 text-sm text-muted-foreground">{detail}</p>}</div>{action}</div>; }
function Status({ value }: { value: string }) { const tone = ['active', 'connected', 'approved', 'present', 'calculated', 'configured', 'completed'].includes(value) ? 'good' : ['attention', 'pending', 'trial', 'draft', 'syncing', 'incomplete'].includes(value) ? 'warn' : ['rejected', 'offline', 'suspended', 'past_due', 'absent', 'outside_geofence'].includes(value) ? 'bad' : 'neutral'; return <Badge tone={tone as any}>{value.replaceAll('_', ' ')}</Badge>; }

function Shell({ children }: { children: ReactNode }) {
  const [location, setLocation] = useLocation();
  const [open, setOpen] = useState(false);
  const workspaceQuery = useGetWorkspace();
  const workspace = workspaceQuery.data || fallbackWorkspace;
  const [locale, setLocale] = useState(() => localStorage.getItem('var-hr-locale') || workspace.locale || 'en');
  useEffect(() => { localStorage.setItem('var-hr-locale', locale); document.documentElement.lang = locale; document.documentElement.dir = locale === 'ar' ? 'rtl' : 'ltr'; }, [locale]);
  const labels: Record<string, string> = { en: 'English', ar: 'العربية', fr: 'Français', de: 'Deutsch' };
  return <div className="app-noise min-h-[100dvh] bg-background">
    <aside className={cn('fixed inset-y-0 start-0 z-50 flex w-[248px] flex-col bg-secondary px-4 py-5 text-sidebar-foreground transition-transform duration-300 lg:translate-x-0', open ? 'translate-x-0' : '-translate-x-full rtl:translate-x-full rtl:lg:translate-x-0')} dir="ltr">
      <div className="flex items-center gap-3 px-3 pb-8"><div className="grid h-9 w-9 place-items-center rounded-lg bg-primary text-primary-foreground"><span className="font-display text-lg font-bold">V</span></div><div><div className="font-display text-[17px] font-bold tracking-tight">VAR HR</div><div className="text-[10px] uppercase tracking-[.18em] text-sidebar-foreground/55">operations desk</div></div></div>
      <div className="mb-3 px-3 text-[10px] font-bold uppercase tracking-[.15em] text-sidebar-foreground/45">Workspace</div>
      <nav className="space-y-1">{nav.map(({ href, label, icon: Icon }) => <Link key={href} href={href} onClick={() => setOpen(false)} data-testid={`link-nav-${label.toLowerCase()}`} className={cn('flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm font-medium transition-colors', location === href ? 'bg-sidebar-accent text-sidebar-accent-foreground' : 'text-sidebar-foreground/70 hover:bg-white/5 hover:text-sidebar-foreground')}><Icon size={17} strokeWidth={1.8} /><span>{label}</span>{href === '/requests' && <span className="ms-auto rounded-full bg-accent px-1.5 py-0.5 text-[10px] font-bold text-secondary">3</span>}</Link>)}</nav>
      <div className="my-5 border-t border-sidebar-border" />
      <div className="mb-3 px-3 text-[10px] font-bold uppercase tracking-[.15em] text-sidebar-foreground/45">Account</div>
      <nav className="space-y-1">{secondaryNav.map(({ href, label, icon: Icon }) => <Link key={href} href={href} onClick={() => setOpen(false)} data-testid={`link-nav-${label.toLowerCase().replaceAll(' ', '-')}`} className={cn('flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm font-medium transition-colors', location === href ? 'bg-sidebar-accent text-sidebar-accent-foreground' : 'text-sidebar-foreground/70 hover:bg-white/5 hover:text-sidebar-foreground')}><Icon size={17} strokeWidth={1.8} /><span>{label}</span></Link>)}</nav>
      <div className="mt-auto rounded-xl border border-white/10 bg-white/5 p-3"><div className="flex items-center gap-2 text-xs font-semibold"><ShieldCheck size={15} className="text-primary" /> Demo-safe workspace</div><p className="mt-1 text-[11px] leading-relaxed text-sidebar-foreground/55">Authentication is not connected. Data remains scoped to the active API workspace.</p></div>
    </aside>
    {open && <button aria-label="Close navigation" onClick={() => setOpen(false)} className="fixed inset-0 z-40 bg-secondary/45 lg:hidden" />}
    <div className="lg:ps-[248px]">
      <header className="sticky top-0 z-30 flex h-[72px] items-center justify-between border-b border-border/80 bg-background/90 px-4 backdrop-blur-md sm:px-8"><div className="flex items-center gap-3"><Button variant="quiet" className="p-2 lg:hidden" onClick={() => setOpen(true)}><Menu size={20} /></Button><div className="hidden text-xs text-muted-foreground sm:block">Active workspace</div><div className="flex items-center gap-2 font-semibold"><Building2 size={16} className="text-primary" />{workspace.company.name}<ChevronDown size={14} className="text-muted-foreground" /></div></div><div className="flex items-center gap-2"><div className="hidden items-center gap-2 rounded-lg border border-border bg-card px-3 py-2 text-xs text-muted-foreground md:flex"><Globe2 size={14} /> <select aria-label="Language" data-testid="select-language" value={locale} onChange={(e) => setLocale(e.target.value)} className="bg-transparent font-medium outline-none">{Object.entries(labels).map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select></div><Button variant="quiet" className="p-2" title="Support" data-testid="button-support"><LifeBuoy size={18} /></Button><div className="grid h-9 w-9 place-items-center rounded-full bg-accent/20 text-xs font-bold text-[#9b512e]">AO</div></div></header>
      <main className="mx-auto max-w-[1500px] px-4 py-7 sm:px-8 sm:py-9">{children}</main>
    </div>
  </div>;
}

function Overview() {
  const q = useGetDashboardSummary(); const d = q.data; const departments = useListDepartments(); const branches = useListBranches();
  if (q.isLoading) return <><Skeleton className="h-10 w-64" /><div className="mt-8 grid gap-4 md:grid-cols-3"><Skeleton className="h-36" /><Skeleton className="h-36" /><Skeleton className="h-36" /></div></>;
  if (q.isError || !d) return <ErrorState retry={() => q.refetch()} />;
  return <div className="animate-in">
    <SectionTitle eyebrow="Monday · operational overview" title="Good morning, Amina." detail={`Decision surface for ${date(d.date)}. Review the exceptions first.`} action={<div className="flex items-center gap-2"><Badge tone="good"><span className="me-1 h-1.5 w-1.5 rounded-full bg-primary" />Live workspace</Badge><Button variant="outline" onClick={() => q.refetch()}><RefreshCw size={15} />Refresh</Button></div>} />
    <div className="grid gap-4 lg:grid-cols-[1.35fr_1fr_1fr]">
      <Card className="overflow-hidden bg-secondary p-5 text-sidebar-foreground sm:p-6"><div className="flex items-start justify-between"><div><p className="text-xs uppercase tracking-[.16em] text-sidebar-foreground/55">Today at a glance</p><h2 className="mt-3 font-display text-4xl font-semibold">{d.attendance.present}<span className="text-lg text-sidebar-foreground/45"> / {d.workforce.activeEmployees}</span></h2><p className="mt-1 text-sm text-sidebar-foreground/65">people accounted for</p></div><div className="rounded-lg bg-primary/20 p-2 text-primary"><Users size={20} /></div></div><div className="mt-7 h-2 overflow-hidden rounded-full bg-white/10"><div className="h-full rounded-full bg-primary" style={{ width: `${Math.min(100, (d.attendance.present / Math.max(1, d.workforce.activeEmployees)) * 100)}%` }} /></div><div className="mt-3 flex justify-between text-xs text-sidebar-foreground/55"><span>{d.attendance.late} late · {d.attendance.absent} absent</span><span>{Math.round((d.attendance.present / Math.max(1, d.workforce.activeEmployees)) * 100)}% presence</span></div></Card>
      <Card className="p-5 sm:p-6"><p className="text-xs uppercase tracking-[.16em] text-muted-foreground">Requests to decide</p><div className="mt-4 flex items-end justify-between"><div className="font-display text-4xl font-semibold">{d.requests.pendingLeave + d.requests.pendingPermissions}</div><ArrowUpRight className="text-accent" size={20} /></div><p className="mt-2 text-sm text-muted-foreground">{d.requests.pendingLeave} leave · {d.requests.pendingPermissions} permission</p><Link href="/requests" className="mt-6 inline-flex text-sm font-bold text-primary hover:underline">Open queue →</Link></Card>
      <Card className="p-5 sm:p-6"><p className="text-xs uppercase tracking-[.16em] text-muted-foreground">Payroll posture</p><div className="mt-4 font-display text-2xl font-semibold">{d.payroll.periodLabel}</div><div className="mt-2 flex items-center gap-2"><Status value={d.payroll.status} /><span className="text-sm text-muted-foreground">{money(d.payroll.totalNet)}</span></div><Link href="/payroll" className="mt-6 inline-flex text-sm font-bold text-primary hover:underline">Inspect calculation →</Link></Card>
    </div>
    <div className="mt-6 grid gap-6 lg:grid-cols-[1.5fr_1fr]">
      <Card><div className="flex items-center justify-between border-b border-border p-5"><div><h2 className="font-display text-lg font-semibold">Signals requiring attention</h2><p className="text-sm text-muted-foreground">Exceptions are intentionally surfaced, not buried.</p></div><AlertCircle size={18} className="text-accent" /></div>{d.alerts?.length ? <div className="divide-y divide-border">{d.alerts.map((a: any) => <div key={a.id} className="flex gap-4 p-5" data-testid={`alert-${a.id}`}><div className={cn('mt-1 h-2 w-2 shrink-0 rounded-full', a.severity === 'critical' ? 'bg-destructive' : a.severity === 'warning' ? 'bg-accent' : 'bg-primary')} /><div><div className="font-semibold">{a.title}</div><p className="mt-1 text-sm text-muted-foreground">{a.detail}</p></div><Badge tone={a.severity === 'critical' ? 'bad' : a.severity === 'warning' ? 'warn' : 'neutral'}>{a.severity}</Badge></div>)}</div> : <Empty title="No alerts in the queue" detail="The operating picture is clean right now." />}</Card>
      <Card><div className="border-b border-border p-5"><h2 className="font-display text-lg font-semibold">Operating footprint</h2><p className="text-sm text-muted-foreground">How the active tenant is structured.</p></div><div className="space-y-1 p-3">{departments.data?.slice(0, 4).map((item: any) => <div className="flex items-center justify-between rounded-lg px-3 py-3 hover:bg-muted/60" key={item.id}><div className="flex items-center gap-3"><div className="grid h-8 w-8 place-items-center rounded-md bg-primary/10 text-primary"><BriefcaseBusiness size={15} /></div><span className="text-sm font-semibold">{item.name}</span></div><span className="font-mono text-xs text-muted-foreground">{item.employeeCount}</span></div>) || <Skeleton className="h-32" />}</div><div className="border-t border-border p-4 text-xs text-muted-foreground">{branches.data?.length || 0} branches · {d.workforce.departments} departments · {d.devices.connected}/{d.devices.total} devices connected</div></Card>
    </div>
  </div>;
}

function Employees() {
  const qc = useQueryClient(); const [search, setSearch] = useState(''); const [status, setStatus] = useState('all'); const [showCreate, setShowCreate] = useState(false); const [selected, setSelected] = useState<string | null>(null);
  const params = useMemo(() => ({ search: search || undefined, status: status as any }), [search, status]); const q = useListEmployees(params); const depts = useListDepartments(); const branches = useListBranches(); const create = useCreateEmployee(); const createDepartment = useCreateDepartment(); const createBranch = useCreateBranch(); const employee = useGetEmployee(selected || '', { query: { enabled: !!selected, queryKey: getGetEmployeeQueryKey(selected || '') } }); const update = useUpdateEmployee();
  const [form, setForm] = useState({ firstName: '', lastName: '', email: '', departmentId: '', branchId: '', joinedOn: new Date().toISOString().slice(0, 10), salary: '0', role: 'employee' });
  function submit(e: FormEvent) { e.preventDefault(); create.mutate({ data: { ...form, salary: Number(form.salary), departmentId: form.departmentId, branchId: form.branchId, role: form.role as any } as any }, { onSuccess: () => { toast.success('Employee added to the workspace'); setShowCreate(false); qc.invalidateQueries({ queryKey: getListEmployeesQueryKey() }); }, onError: () => toast.error('Could not create employee') }); }
  return <div className="animate-in"><SectionTitle eyebrow="Workforce registry" title="Employees" detail="Search, review, and maintain the people behind the operating picture." action={<Button onClick={() => setShowCreate(true)} data-testid="button-create-employee"><Plus size={16} />Add employee</Button>} /><Card><div className="flex flex-col gap-3 border-b border-border p-4 sm:flex-row"><div className="relative flex-1"><Search className="absolute start-3 top-2.5 text-muted-foreground" size={16} /><input data-testid="input-employee-search" value={search} onChange={e => setSearch(e.target.value)} placeholder="Search by name, number, or email" className="h-10 w-full rounded-lg border border-input bg-background ps-9 pe-3 text-sm outline-none focus:border-primary" /></div><select data-testid="select-employee-status" value={status} onChange={e => setStatus(e.target.value)} className="h-10 rounded-lg border border-input bg-background px-3 text-sm"><option value="all">All statuses</option><option value="active">Active</option><option value="inactive">Inactive</option></select></div>{q.isLoading ? <div className="space-y-3 p-5"><Skeleton className="h-12" /><Skeleton className="h-12" /><Skeleton className="h-12" /></div> : q.isError ? <ErrorState retry={() => q.refetch()} /> : q.data?.length ? <div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left text-sm rtl:text-right"><thead className="bg-muted/50 text-[11px] uppercase tracking-wider text-muted-foreground"><tr><th className="px-5 py-3">Employee</th><th className="px-4 py-3">Department</th><th className="px-4 py-3">Branch</th><th className="px-4 py-3">Role</th><th className="px-4 py-3">Status</th><th className="px-5 py-3 text-right rtl:text-left">Joined</th></tr></thead><tbody className="divide-y divide-border">{q.data.map((item: any) => <tr key={item.id} onClick={() => setSelected(item.id)} className="cursor-pointer transition-colors hover:bg-muted/40" data-testid={`row-employee-${item.id}`}><td className="px-5 py-4"><div className="flex items-center gap-3"><div className="grid h-9 w-9 place-items-center rounded-full bg-primary/10 text-xs font-bold text-primary">{item.avatarInitials || `${item.firstName[0]}${item.lastName[0]}`}</div><div><div className="font-semibold">{item.firstName} {item.lastName}</div><div className="text-xs text-muted-foreground">{item.employeeNumber} · {item.email}</div></div></div></td><td className="px-4 py-4">{item.department?.name}</td><td className="px-4 py-4">{item.branch?.name}</td><td className="px-4 py-4 capitalize">{item.role}</td><td className="px-4 py-4"><Status value={item.status} /></td><td className="px-5 py-4 text-right text-muted-foreground rtl:text-left">{date(item.joinedOn)}</td></tr>)}</tbody></table></div> : <Empty title="No employees match this view" detail="Adjust the search or add the first employee to this tenant." action={<Button onClick={() => setShowCreate(true)}><Plus size={15} />Add employee</Button>} />}</Card>
    {showCreate && <Modal title="Add employee" onClose={() => setShowCreate(false)}><form onSubmit={submit} className="space-y-4">{[['firstName','First name'],['lastName','Last name'],['email','Email'],['salary','Monthly salary']].map(([key,label]) => <label key={key} className="block text-sm font-semibold">{label}<input required={key !== 'salary'} type={key === 'salary' ? 'number' : key === 'email' ? 'email' : 'text'} value={(form as any)[key]} onChange={e => setForm({...form, [key]: e.target.value})} className="mt-1 h-10 w-full rounded-lg border border-input bg-background px-3 text-sm font-normal outline-none focus:border-primary" /></label>)}<div className="grid gap-4 sm:grid-cols-2"><label className="text-sm font-semibold">Department<div className="mt-1 flex gap-2"><select required value={form.departmentId} onChange={e => setForm({...form,departmentId:e.target.value})} className="h-10 min-w-0 flex-1 rounded-lg border border-input bg-background px-2 text-sm font-normal"><option value="">Select</option>{depts.data?.map((x:any)=><option key={x.id} value={x.id}>{x.name}</option>)}</select><Button type="button" variant="outline" className="px-2" title="Create department" onClick={()=>{const name=window.prompt('Department name');if(name)createDepartment.mutate({data:{name}},{onSuccess:()=>{toast.success('Department created');qc.invalidateQueries({queryKey:getListDepartmentsQueryKey()})}})}}><Plus size={15}/></Button></div></label><label className="text-sm font-semibold">Branch<div className="mt-1 flex gap-2"><select required value={form.branchId} onChange={e => setForm({...form,branchId:e.target.value})} className="h-10 min-w-0 flex-1 rounded-lg border border-input bg-background px-2 text-sm font-normal"><option value="">Select</option>{branches.data?.map((x:any)=><option key={x.id} value={x.id}>{x.name}</option>)}</select><Button type="button" variant="outline" className="px-2" title="Create branch" onClick={()=>{const name=window.prompt('Branch name');const city=window.prompt('Branch city');if(name&&city)createBranch.mutate({data:{name,city,gpsEnabled:false}},{onSuccess:()=>{toast.success('Branch created');qc.invalidateQueries({queryKey:getListBranchesQueryKey()})}})}}><Plus size={15}/></Button></div></label></div><div className="flex justify-end gap-2 pt-2"><Button type="button" variant="quiet" onClick={() => setShowCreate(false)}>Cancel</Button><Button disabled={create.isPending} type="submit">{create.isPending ? 'Saving…' : 'Create employee'}</Button></div></form></Modal>}
    {selected && <Modal title="Employee profile" onClose={() => setSelected(null)}>{employee.isLoading ? <Skeleton className="h-40" /> : employee.data ? <div><div className="flex items-center gap-3"><div className="grid h-12 w-12 place-items-center rounded-full bg-primary/10 font-bold text-primary">{employee.data.avatarInitials}</div><div><h3 className="font-display text-xl font-semibold">{employee.data.firstName} {employee.data.lastName}</h3><p className="text-sm text-muted-foreground">{employee.data.email}</p></div></div><div className="mt-6 grid grid-cols-2 gap-3 text-sm"><Info label="Employee number" value={employee.data.employeeNumber} /><Info label="Department" value={employee.data.department?.name} /><Info label="Branch" value={employee.data.branch?.name} /><Info label="Salary" value={money(employee.data.salary)} /></div><Button className="mt-6" variant="outline" onClick={() => update.mutate({ employeeId: employee.data.id, data: { status: employee.data.status === 'active' ? 'inactive' : 'active' } as any }, { onSuccess: () => { toast.success('Employee status updated'); qc.invalidateQueries({ queryKey: getListEmployeesQueryKey() }); qc.invalidateQueries({ queryKey: getGetEmployeeQueryKey(employee.data.id) }); } })}>{employee.data.status === 'active' ? 'Mark inactive' : 'Reactivate employee'}</Button></div> : <ErrorState retry={() => employee.refetch()} />}</Modal>}
  </div>;
}

function Attendance() {
  const qc = useQueryClient(); const [tab, setTab] = useState('today'); const today = useGetAttendanceToday(); const history = useListAttendanceHistory(); const checkIn = useCheckIn(); const checkOut = useCheckOut();
  const record = today.data?.records?.[0]; const action = record?.checkIn && !record.checkOut ? 'out' : 'in';
  function event(kind: 'in'|'out') { (kind === 'in' ? checkIn : checkOut).mutate({ data: { source: 'web' } as any }, { onSuccess: () => { toast.success(kind === 'in' ? 'Check-in recorded' : 'Check-out recorded'); qc.invalidateQueries({ queryKey: getGetAttendanceTodayQueryKey() }); qc.invalidateQueries({ queryKey: getListAttendanceHistoryQueryKey() }); }, onError: () => toast.error('Attendance event was not accepted') }); }
  return <div className="animate-in"><SectionTitle eyebrow="Time & presence" title="Attendance" detail="The current employee context is used for check-in and check-out. History remains auditable." action={<div className="flex gap-2"><Button variant={tab === 'today' ? 'primary' : 'outline'} onClick={() => setTab('today')}>Today</Button><Button variant={tab === 'history' ? 'primary' : 'outline'} onClick={() => setTab('history')}>History</Button></div>} />{tab === 'today' ? <div className="grid gap-6 lg:grid-cols-[.8fr_1.2fr]"><Card className="bg-secondary p-6 text-sidebar-foreground"><p className="text-xs uppercase tracking-[.16em] text-sidebar-foreground/55">Current employee context</p><h2 className="mt-3 font-display text-2xl font-semibold">{record?.employee?.name || 'No employee context'}</h2><p className="mt-1 text-sm text-sidebar-foreground/60">{record?.employee?.department || 'The API will identify the signed-in employee.'}</p><div className="my-8 h-px bg-white/10" /><div className="flex items-center justify-between"><div><p className="text-xs text-sidebar-foreground/50">Status</p><div className="mt-1">{record ? <Status value={record.status} /> : <Badge>Not available</Badge>}</div></div><div className="text-right"><p className="text-xs text-sidebar-foreground/50">Scheduled start</p><p className="mt-1 font-mono text-lg">{record?.scheduledStart || '—'}</p></div></div><Button disabled={!record || (action === 'in' ? checkIn.isPending : checkOut.isPending)} onClick={() => event(action)} className="mt-7 w-full bg-accent text-secondary hover:bg-accent/90">{action === 'in' ? 'Check in now' : 'Check out now'} <ArrowUpRight size={16} /></Button><p className="mt-3 text-center text-[11px] text-sidebar-foreground/45">Web event · location policy is evaluated by the API</p></Card><Card><div className="border-b border-border p-5"><h2 className="font-display text-lg font-semibold">Today’s register</h2><p className="text-sm text-muted-foreground">{today.data?.date ? date(today.data.date) : 'Loading operational date'}</p></div>{today.isLoading ? <div className="space-y-3 p-5"><Skeleton className="h-12" /><Skeleton className="h-12" /></div> : today.isError ? <ErrorState retry={() => today.refetch()} /> : today.data?.records?.length ? <div className="divide-y divide-border">{today.data.records.slice(0, 8).map((x:any)=><div className="flex items-center justify-between gap-4 p-4" key={x.id}><div className="flex items-center gap-3"><div className="grid h-9 w-9 place-items-center rounded-full bg-muted text-xs font-bold">{x.employee.initials}</div><div><div className="font-semibold">{x.employee.name}</div><div className="text-xs text-muted-foreground">{time(x.checkIn)} → {time(x.checkOut)} · {x.workedHours}h worked</div></div></div><Status value={x.status} /></div>)}</div> : <Empty title="No attendance records yet" detail="When the day starts, events will appear here." />}</Card></div> : <Card>{history.isLoading ? <Skeleton className="m-5 h-48" /> : history.isError ? <ErrorState retry={() => history.refetch()} /> : history.data?.length ? <div className="overflow-x-auto"><table className="w-full min-w-[700px] text-sm"><thead className="bg-muted/50 text-left text-[11px] uppercase tracking-wider text-muted-foreground"><tr><th className="px-5 py-3">Date</th><th className="px-4 py-3">Employee</th><th className="px-4 py-3">Check in</th><th className="px-4 py-3">Check out</th><th className="px-4 py-3">Hours</th><th className="px-5 py-3">Status</th></tr></thead><tbody className="divide-y divide-border">{history.data.map((x:any)=><tr key={x.id}><td className="px-5 py-4">{date(x.date)}</td><td className="px-4 py-4 font-semibold">{x.employee.name}</td><td className="px-4 py-4">{time(x.checkIn)}</td><td className="px-4 py-4">{time(x.checkOut)}</td><td className="px-4 py-4 font-mono">{x.workedHours}</td><td className="px-5 py-4"><Status value={x.status} /></td></tr>)}</tbody></table></div> : <Empty title="No history found" detail="Attendance history will populate once events are recorded." />}</Card>}</div>;
}

function Requests() {
  const qc = useQueryClient(); const [kind, setKind] = useState<'leave'|'permission'>('leave'); const [show, setShow] = useState(false); const balances = useListLeaveBalances(); const leaves = useListLeaveRequests(); const permissions = useListPermissionRequests(); const createLeave = useCreateLeaveRequest(); const createPermission = useCreatePermissionRequest(); const decideLeave = useDecideLeaveRequest(); const decidePermission = useDecidePermissionRequest(); const [form, setForm] = useState<any>({ type: 'Annual leave', from: '', to: '', reason: '', date: '', startTime: '', endTime: '' });
  function submit(e: FormEvent) { e.preventDefault(); const mutation = kind === 'leave' ? createLeave : createPermission; const data = kind === 'leave' ? { type: form.type, from: form.from, to: form.to, reason: form.reason } : { type: form.type, date: form.date, startTime: form.startTime, endTime: form.endTime, reason: form.reason }; mutation.mutate({ data } as any, { onSuccess: () => { toast.success('Request submitted'); setShow(false); qc.invalidateQueries({ queryKey: kind === 'leave' ? getListLeaveRequestsQueryKey() : getListPermissionRequestsQueryKey() }); }, onError: () => toast.error('Could not submit request') }); }
  function decide(id: string, approved: boolean, type: 'leave'|'permission') { const mutation = type === 'leave' ? decideLeave : decidePermission; mutation.mutate({ requestId: id, data: { decision: approved ? 'approved' : 'rejected', reason: approved ? 'Reviewed in operations queue' : 'Not approved at this time' } as any }, { onSuccess: () => { toast.success(approved ? 'Request approved' : 'Request rejected'); qc.invalidateQueries({ queryKey: type === 'leave' ? getListLeaveRequestsQueryKey() : getListPermissionRequestsQueryKey() }); } }); }
  const rows: any[] = kind === 'leave' ? (leaves.data || []) : (permissions.data || []);
  return <div className="animate-in"><SectionTitle eyebrow="Decision queue" title="Requests" detail="Approve with context. Every decision stays attached to the request." action={<Button onClick={() => setShow(true)} data-testid="button-create-request"><Plus size={16} />New request</Button>} /><div className="grid gap-6 lg:grid-cols-[.72fr_1.28fr]"><div className="space-y-4"><Card className="p-5"><div className="flex items-center gap-2"><CalendarDays size={17} className="text-primary" /><h2 className="font-display font-semibold">Leave balances</h2></div><div className="mt-4 space-y-3">{balances.data?.map((b:any)=><div key={b.id}><div className="flex justify-between text-sm"><span className="font-semibold">{b.type}</span><span className="font-mono text-xs text-muted-foreground">{b.remaining} days remaining</span></div><div className="mt-2 h-1.5 rounded-full bg-muted"><div className="h-full rounded-full bg-primary" style={{width:`${Math.min(100,(b.used/Math.max(1,b.allocated))*100)}%`}} /></div></div>) || <Skeleton className="h-24" />}</div></Card><Card className="p-5"><p className="text-xs uppercase tracking-[.16em] text-muted-foreground">Queue hygiene</p><p className="mt-2 text-3xl font-display font-semibold">{(leaves.data || []).filter((x:any)=>x.status==='pending').length + (permissions.data || []).filter((x:any)=>x.status==='pending').length}</p><p className="text-sm text-muted-foreground">pending decisions across both request types</p></Card></div><Card><div className="flex flex-wrap items-center justify-between gap-3 border-b border-border p-4"><div className="flex gap-1 rounded-lg bg-muted p-1"><Button className="px-3 py-1.5 text-xs" variant={kind === 'leave' ? 'primary' : 'quiet'} onClick={() => setKind('leave')}>Leave</Button><Button className="px-3 py-1.5 text-xs" variant={kind === 'permission' ? 'primary' : 'quiet'} onClick={() => setKind('permission')}>Permission</Button></div><span className="text-xs text-muted-foreground">{rows.length} records</span></div>{rows.length ? <div className="divide-y divide-border">{rows.map((r:any)=><div className="p-5" key={r.id}><div className="flex flex-col justify-between gap-3 sm:flex-row"><div><div className="flex items-center gap-2"><span className="font-semibold">{r.employee.name}</span><Status value={r.status} /></div><p className="mt-1 text-sm text-muted-foreground">{r.type} · {kind === 'leave' ? `${date(r.from)} – ${date(r.to)} · ${r.days} days` : `${date(r.date)} · ${r.startTime} – ${r.endTime}`}</p><p className="mt-3 text-sm">{r.reason}</p></div>{r.status === 'pending' && <div className="flex shrink-0 gap-2"><Button variant="outline" className="text-primary" onClick={() => decide(r.id,true,kind)}><Check size={15} />Approve</Button><Button variant="danger" onClick={() => decide(r.id,false,kind)}><X size={15} />Reject</Button></div>}</div></div>)}</div> : <Empty title="The decision queue is clear" detail="New leave and permission requests will appear here." action={<Button onClick={() => setShow(true)}><Plus size={15} />Create request</Button>} />}</Card></div>{show && <Modal title={`New ${kind} request`} onClose={() => setShow(false)}><form onSubmit={submit} className="space-y-4"><label className="block text-sm font-semibold">Type<input required value={form.type} onChange={e=>setForm({...form,type:e.target.value})} className="mt-1 h-10 w-full rounded-lg border border-input bg-background px-3 text-sm font-normal" /></label>{kind === 'leave' ? <div className="grid grid-cols-2 gap-3"><Field label="From" type="date" value={form.from} onChange={(v)=>setForm({...form,from:v})} required /><Field label="To" type="date" value={form.to} onChange={(v)=>setForm({...form,to:v})} required /></div> : <div className="grid gap-3 sm:grid-cols-3"><Field label="Date" type="date" value={form.date} onChange={(v)=>setForm({...form,date:v})} required /><Field label="Start" type="time" value={form.startTime} onChange={(v)=>setForm({...form,startTime:v})} required /><Field label="End" type="time" value={form.endTime} onChange={(v)=>setForm({...form,endTime:v})} required /></div>}<label className="block text-sm font-semibold">Reason<textarea required value={form.reason} onChange={e=>setForm({...form,reason:e.target.value})} className="mt-1 min-h-24 w-full rounded-lg border border-input bg-background p-3 text-sm font-normal" /></label><div className="flex justify-end gap-2"><Button type="button" variant="quiet" onClick={()=>setShow(false)}>Cancel</Button><Button type="submit">Submit request</Button></div></form></Modal>}</div>;
}

function Rules() {
  const qc = useQueryClient(); const q = useGetAttendanceRules(); const update = useUpdateAttendanceRules(); const [form, setForm] = useState<any>(null); useEffect(()=>{ if(q.data && !form) setForm({...q.data}); },[q.data,form]);
  if(q.isLoading || !form) return <Skeleton className="h-64" />; if(q.isError) return <ErrorState retry={()=>q.refetch()} />;
  function save(e:FormEvent){e.preventDefault(); update.mutate({data:{...form,graceMinutes:Number(form.graceMinutes),overtimeAfterMinutes:Number(form.overtimeAfterMinutes),locationRadiusMeters:Number(form.locationRadiusMeters)} as any},{onSuccess:()=>{toast.success('Attendance policy updated');qc.invalidateQueries({queryKey:getGetAttendanceRulesQueryKey()})}})}
  const rules = q.data as any;
  return <div className="animate-in"><SectionTitle eyebrow="Policy control" title="Attendance rules" detail="Versioned operating policy for time, overtime, and location verification." action={<Badge tone="accent">Version {rules.version || 1}</Badge>} /><form onSubmit={save} className="grid gap-6 lg:grid-cols-[1.2fr_.8fr]"><Card className="p-6"><h2 className="font-display text-lg font-semibold">Working hours</h2><p className="mt-1 text-sm text-muted-foreground">Changes apply from the effective date. No legal or statutory interpretation is implied.</p><div className="mt-6 grid gap-5 sm:grid-cols-2"><Field label="Work starts" type="time" value={form.workStart} onChange={v=>setForm({...form,workStart:v})} /><Field label="Work ends" type="time" value={form.workEnd} onChange={v=>setForm({...form,workEnd:v})} /><Field label="Grace period (minutes)" type="number" value={form.graceMinutes} onChange={v=>setForm({...form,graceMinutes:v})} /><Field label="Overtime after (minutes)" type="number" value={form.overtimeAfterMinutes} onChange={v=>setForm({...form,overtimeAfterMinutes:v})} /></div><div className="mt-7 flex flex-wrap gap-2">{['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map((day,i)=><button type="button" key={day} onClick={()=>{const val=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][i];const days=form.workingDays || [];setForm({...form,workingDays:days.includes(val)?days.filter((x:string)=>x!==val):[...days,val]})}} className={cn('rounded-lg border px-3 py-2 text-xs font-bold', (form.workingDays || []).includes(day) ? 'border-primary bg-primary/10 text-primary' : 'border-border text-muted-foreground')}>{day}</button>)}</div></Card><div className="space-y-6"><Card className="p-6"><h2 className="font-display text-lg font-semibold">Location verification</h2><div className="mt-5 space-y-4"><label className="block text-sm font-semibold">GPS policy<select value={form.gpsPolicy} onChange={e=>setForm({...form,gpsPolicy:e.target.value})} className="mt-1 h-10 w-full rounded-lg border border-input bg-background px-3 text-sm font-normal"><option value="disabled">Disabled</option><option value="optional">Optional</option><option value="required">Required</option></select></label><Field label="Location radius (meters)" type="number" value={form.locationRadiusMeters} onChange={v=>setForm({...form,locationRadiusMeters:v})} /></div></Card><Card className="bg-muted/50 p-5"><div className="flex gap-3"><CircleHelp size={17} className="mt-0.5 text-primary" /><div><h3 className="text-sm font-semibold">Explainability by default</h3><p className="mt-1 text-xs leading-relaxed text-muted-foreground">Attendance exceptions record their source, location posture, and a human-readable explanation for review.</p></div></div></Card><Button type="submit" disabled={update.isPending} className="w-full">{update.isPending ? 'Saving policy…' : 'Save attendance policy'}</Button></div></form></div>;
}

function Reports() { const [from,setFrom]=useState('');const [to,setTo]=useState(''); const params=useMemo(()=>({from:from||undefined,to:to||undefined}),[from,to]); const q=useGetAttendanceReport(params); return <div className="animate-in"><SectionTitle eyebrow="Evidence & analysis" title="Attendance reports" detail="Preview the selected period before exporting through your connected workflow." action={<Button variant="outline" onClick={()=>q.refetch()}><RefreshCw size={15}/>Refresh preview</Button>} /><Card className="mb-6 p-4"><div className="grid gap-3 sm:grid-cols-[1fr_1fr_auto] sm:items-end"><Field label="From" type="date" value={from} onChange={setFrom}/><Field label="To" type="date" value={to} onChange={setTo}/><Button onClick={()=>q.refetch()}><BarChart3 size={15}/>Preview report</Button></div></Card>{q.isLoading?<Skeleton className="h-60"/>:q.isError?<ErrorState retry={()=>q.refetch()}/>:q.data?<><div className="grid gap-4 sm:grid-cols-4">{[['Present',q.data.totals.present],['Late',q.data.totals.late],['Absent',q.data.totals.absent],['Overtime hours',q.data.totals.overtimeHours]].map(([l,v])=><Card key={String(l)} className="p-4"><div className="text-xs uppercase tracking-wider text-muted-foreground">{l}</div><div className="mt-2 font-display text-2xl font-semibold">{v}</div></Card>)}</div><Card className="mt-6 overflow-hidden"><div className="border-b border-border p-5"><h2 className="font-display text-lg font-semibold">Employee detail</h2><p className="text-sm text-muted-foreground">{date(q.data.from)} – {date(q.data.to)}</p></div><div className="overflow-x-auto"><table className="w-full min-w-[680px] text-sm"><thead className="bg-muted/50 text-left text-[11px] uppercase tracking-wider text-muted-foreground"><tr><th className="px-5 py-3">Employee</th><th className="px-4 py-3">Present</th><th className="px-4 py-3">Late</th><th className="px-4 py-3">Absent</th><th className="px-4 py-3">Worked</th><th className="px-5 py-3">Overtime</th></tr></thead><tbody className="divide-y divide-border">{q.data.rows.map((r:any)=><tr key={r.employee.id}><td className="px-5 py-4 font-semibold">{r.employee.name}</td><td className="px-4 py-4">{r.presentDays}</td><td className="px-4 py-4">{r.lateDays}</td><td className="px-4 py-4">{r.absentDays}</td><td className="px-4 py-4 font-mono">{r.workedHours}h</td><td className="px-5 py-4 font-mono">{r.overtimeHours}h</td></tr>)}</tbody></table></div></Card></>:<Empty title="Choose a reporting window" detail="Set the dates above to preview attendance evidence."/>}</div>; }

function Payroll() { const qc=useQueryClient();const q=useListPayrollPeriods();const calc=useCalculatePayroll();const [selected,setSelected]=useState<any>(null); function calculate(id:string){calc.mutate({periodId:id},{onSuccess:(data:any)=>{toast.success('Payroll calculation ready');setSelected(data);qc.invalidateQueries({queryKey:getListPayrollPeriodsQueryKey()})},onError:()=>toast.error('Calculation could not be completed')})} return <div className="animate-in"><SectionTitle eyebrow="General payroll operations" title="Payroll" detail="Explainable calculation history using configured workforce inputs. This is not statutory tax advice." /><div className="grid gap-6 lg:grid-cols-[.8fr_1.2fr]"><Card><div className="border-b border-border p-5"><h2 className="font-display text-lg font-semibold">Periods</h2><p className="text-sm text-muted-foreground">Select a period to inspect or recalculate.</p></div>{q.isLoading?<div className="space-y-3 p-5"><Skeleton className="h-14"/><Skeleton className="h-14"/></div>:q.isError?<ErrorState retry={()=>q.refetch()}/>:q.data?.length?<div className="divide-y divide-border">{q.data.map((p:any)=><button className={cn('block w-full p-5 text-left transition-colors hover:bg-muted/40',selected?.period?.id===p.id&&'bg-primary/5')} key={p.id} onClick={()=>setSelected(null)}><div className="flex items-center justify-between gap-3"><div><div className="font-semibold">{p.label}</div><div className="mt-1 text-xs text-muted-foreground">{date(p.from)} – {date(p.to)} · {p.employeeCount} employees</div></div><Status value={p.status}/></div><div className="mt-3 flex items-center justify-between text-sm"><span className="font-mono">{money(p.totalNet)}</span><Button type="button" variant="outline" className="px-2 py-1 text-xs" onClick={(e)=>{e.stopPropagation();calculate(p.id)}}>{calc.isPending?'Calculating…':'Calculate'}</Button></div></button>)}</div>:<Empty title="No payroll periods" detail="Periods are supplied by the operational API."/>}</Card><Card>{selected?<div><div className="flex items-start justify-between border-b border-border p-5"><div><p className="text-xs uppercase tracking-wider text-primary">Calculation history</p><h2 className="mt-1 font-display text-lg font-semibold">{selected.period.label}</h2><p className="mt-1 text-sm text-muted-foreground">Calculated {date(selected.calculatedAt)}</p></div><Badge tone="good">Explainable</Badge></div><div className="grid grid-cols-2 gap-3 p-5 sm:grid-cols-4">{[['Basic',selected.totals.basicSalary],['Additions',selected.totals.additions],['Overtime',selected.totals.overtime],['Net salary',selected.totals.netSalary]].map(([l,v])=><div key={String(l)} className="rounded-lg bg-muted/60 p-3"><div className="text-[11px] uppercase tracking-wider text-muted-foreground">{l}</div><div className="mt-1 font-mono text-sm font-semibold">{money(Number(v))}</div></div>)}</div><div className="border-t border-border p-5"><h3 className="text-sm font-semibold">Calculation explanation</h3><p className="mt-2 text-sm leading-relaxed text-muted-foreground">{selected.explanation}</p></div></div>:<Empty title="Select a period" detail="Choose Calculate to create an explainable calculation preview."/>}</Card></div></div>; }

function Devices() { const qc=useQueryClient();const q=useListDevices();const branches=useListBranches();const create=useCreateDevice();const sync=useSyncDevice();const [show,setShow]=useState(false);const [form,setForm]=useState({name:'',manufacturer:'',model:'',branchId:''});function submit(e:FormEvent){e.preventDefault();create.mutate({data:form},{onSuccess:()=>{toast.success('Device configuration added');setShow(false);qc.invalidateQueries({queryKey:getListDevicesQueryKey()})},onError:()=>toast.error('Could not add device')})}return <div className="animate-in"><SectionTitle eyebrow="Connected operations" title="Biometric devices" detail="Configuration is visible here; adapter availability is reported honestly." action={<Button onClick={()=>setShow(true)}><Plus size={16}/>Add device</Button>}/><Card>{q.isLoading?<Skeleton className="m-5 h-48"/>:q.isError?<ErrorState retry={()=>q.refetch()}/>:q.data?.length?<div className="divide-y divide-border">{q.data.map((d:any)=><div className="flex flex-col justify-between gap-4 p-5 sm:flex-row sm:items-center" key={d.id}><div className="flex items-center gap-4"><div className="grid h-11 w-11 place-items-center rounded-lg bg-secondary text-primary"><Fingerprint size={21}/></div><div><div className="flex items-center gap-2 font-semibold">{d.name}<Status value={d.status}/></div><p className="mt-1 text-sm text-muted-foreground">{d.manufacturer} {d.model} · {d.branch}</p><p className="mt-1 text-xs text-muted-foreground">{d.note || `Last sync: ${d.lastSync ? date(d.lastSync) : 'never'}`}</p></div></div><div className="flex items-center gap-3"><Status value={d.integrationState}/><Button variant="outline" disabled={d.integrationState==='adapter_pending'||sync.isPending} onClick={()=>sync.mutate({deviceId:d.id},{onSuccess:(r:any)=>{toast.success(r.message || 'Sync requested');qc.invalidateQueries({queryKey:getListDevicesQueryKey()})},onError:()=>toast.error('Sync request unavailable')})}><RefreshCw size={15}/>Sync</Button></div></div>)}</div>:<Empty title="No biometric devices configured" detail="Add a device to make its adapter state visible." action={<Button onClick={()=>setShow(true)}><Plus size={15}/>Add device</Button>}/>}</Card>{show&&<Modal title="Add biometric device" onClose={()=>setShow(false)}><form onSubmit={submit} className="space-y-4">{[['name','Device name'],['manufacturer','Manufacturer'],['model','Model']].map(([k,l])=><label key={k} className="block text-sm font-semibold">{l}<input required value={(form as any)[k]} onChange={e=>setForm({...form,[k]:e.target.value})} className="mt-1 h-10 w-full rounded-lg border border-input bg-background px-3 text-sm font-normal"/></label>)}<label className="block text-sm font-semibold">Branch<select required value={form.branchId} onChange={e=>setForm({...form,branchId:e.target.value})} className="mt-1 h-10 w-full rounded-lg border border-input bg-background px-2 text-sm font-normal"><option value="">Select branch</option>{branches.data?.map((b:any)=><option key={b.id} value={b.id}>{b.name}</option>)}</select></label><div className="flex justify-end gap-2"><Button type="button" variant="quiet" onClick={()=>setShow(false)}>Cancel</Button><Button type="submit">Add configuration</Button></div></form></Modal>}</div>; }

function Subscription() { const q=useGetSubscription(); if(q.isLoading)return <Skeleton className="h-64"/>;if(q.isError)return <ErrorState retry={()=>q.refetch()}/>;const d=q.data!;const pct=Math.min(100,(d.activeEmployees/d.employeeLimit)*100);return <div className="animate-in"><SectionTitle eyebrow="Plan & capacity" title="Subscription" detail="Usage and entitlements for the active workspace."/><div className="grid gap-6 lg:grid-cols-[1fr_1fr]"><Card className="bg-secondary p-6 text-sidebar-foreground"><div className="flex items-start justify-between"><div><p className="text-xs uppercase tracking-[.16em] text-sidebar-foreground/55">Current plan</p><h2 className="mt-3 font-display text-3xl font-semibold">{d.planName}</h2></div><Status value={d.status}/></div><div className="mt-10 flex items-end justify-between"><span className="text-sm text-sidebar-foreground/60">Active employees</span><span className="font-mono text-sm">{d.activeEmployees} / {d.employeeLimit}</span></div><div className="mt-2 h-2 rounded-full bg-white/10"><div className="h-full rounded-full bg-accent" style={{width:`${pct}%`}}/></div><p className="mt-3 text-xs text-sidebar-foreground/55">{Math.max(0,d.employeeLimit-d.activeEmployees)} seats remaining</p></Card><Card className="p-6"><h2 className="font-display text-lg font-semibold">Included capabilities</h2><div className="mt-4 grid gap-2 sm:grid-cols-2">{d.features.map((x:string)=><div className="flex items-center gap-2 rounded-lg bg-muted/60 p-3 text-sm" key={x}><Check size={15} className="text-primary"/>{x}</div>)}</div><div className="mt-6 rounded-lg border border-accent/25 bg-accent/10 p-4 text-sm text-[#86502f]">Plan changes are managed through your account team. No billing action is simulated here.</div></Card></div></div>; }

function Platform() { const q=useListPlatformCompanies();return <div className="animate-in"><SectionTitle eyebrow="Separate administration surface" title="Platform owner" detail="Cross-tenant visibility for platform operations. Company actions are intentionally read-only in this surface." action={<Badge tone="accent">Platform scope</Badge>}/><Card>{q.isLoading?<Skeleton className="m-5 h-48"/>:q.isError?<ErrorState retry={()=>q.refetch()}/>:q.data?.length?<div className="overflow-x-auto"><table className="w-full min-w-[760px] text-sm"><thead className="bg-muted/50 text-left text-[11px] uppercase tracking-wider text-muted-foreground"><tr><th className="px-5 py-3">Company</th><th className="px-4 py-3">Status</th><th className="px-4 py-3">Plan</th><th className="px-4 py-3">Seats</th><th className="px-5 py-3">Last activity</th></tr></thead><tbody className="divide-y divide-border">{q.data.map((c:any)=><tr key={c.id}><td className="px-5 py-4 font-semibold">{c.name}</td><td className="px-4 py-4"><Status value={c.status}/></td><td className="px-4 py-4">{c.planName}</td><td className="px-4 py-4 font-mono text-xs">{c.activeEmployees} / {c.employeeLimit}</td><td className="px-5 py-4 text-muted-foreground">{date(c.lastActivity)}</td></tr>)}</tbody></table></div>:<Empty title="No companies in platform scope" detail="The platform API returned no tenants for this workspace."/>}</Card></div>; }

function Modal({ title, onClose, children }: { title:string;onClose:()=>void;children:ReactNode }) { return <div className="fixed inset-0 z-[60] grid place-items-center bg-secondary/45 p-4"><div role="dialog" aria-modal="true" className="max-h-[90dvh] w-full max-w-lg overflow-y-auto rounded-2xl border border-border bg-card p-6 shadow-[var(--shadow-md)] animate-in"><div className="mb-5 flex items-center justify-between"><h2 className="font-display text-xl font-semibold">{title}</h2><Button variant="quiet" className="p-2" onClick={onClose} aria-label="Close dialog"><X size={18}/></Button></div>{children}</div></div>; }
function Field({ label, value, onChange, type='text', required=false }: {label:string;value:any;onChange:(value:string)=>void;type?:string;required?:boolean}) { return <label className="block text-sm font-semibold">{label}<input required={required} type={type} value={value ?? ''} onChange={e=>onChange(e.target.value)} className="mt-1 h-10 w-full rounded-lg border border-input bg-background px-3 text-sm font-normal outline-none focus:border-primary"/></label>; }
function Info({ label, value }: {label:string;value:any}) { return <div className="rounded-lg bg-muted/60 p-3"><div className="text-[11px] uppercase tracking-wider text-muted-foreground">{label}</div><div className="mt-1 font-medium">{value || '—'}</div></div>; }

function Router() { return <Shell><Switch><Route path="/" component={Overview}/><Route path="/employees" component={Employees}/><Route path="/attendance" component={Attendance}/><Route path="/requests" component={Requests}/><Route path="/rules" component={Rules}/><Route path="/reports" component={Reports}/><Route path="/payroll" component={Payroll}/><Route path="/devices" component={Devices}/><Route path="/subscription" component={Subscription}/><Route path="/platform" component={Platform}/><Route component={NotFound}/></Switch></Shell>; }
function App() { return <QueryClientProvider client={queryClient}><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><ErrorBoundary><Router/></ErrorBoundary></WouterRouter><Toaster position="bottom-right" richColors/></QueryClientProvider>; }
export default App;